/* ==========================================================================
   Web Piano App - Global & Theme Styles
   ========================================================================== */

:root {
  --bg-gradient-start: #1a1e29;
  --bg-gradient-end: #12141c;
  --piano-body-color: #1c1d22;
  --piano-trim-gold: #c8963e;
  --piano-felt-red: #9e1a1a;

  --white-key-base: #fdfdfd;
  --white-key-grad: #e5e5eb;
  --white-key-active: #d6e2f5;
  --white-key-border: #b8b8c2;

  --black-key-base: #282a32;
  --black-key-top: #15161b;
  --black-key-active: #3c5488;
  --black-key-border: #0a0b0d;

  --accent-blue: #3b82f6;
  --accent-blue-hover: #2563eb;
  --accent-red: #ef4444;
  --accent-red-hover: #dc2626;

  --text-main: #f3f4f6;
  --text-muted: #9ca3af;
  --panel-bg: rgba(30, 33, 44, 0.75);
  --panel-border: rgba(255, 255, 255, 0.08);

  --font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, "Helvetica Neue", Arial, sans-serif;
}

*, *::before, *::after {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

body {
  font-family: var(--font-family);
  background: radial-gradient(circle at 50% 20%, var(--bg-gradient-start), var(--bg-gradient-end));
  color: var(--text-main);
  min-height: 100vh;
  display: flex;
  justify-content: center;
  align-items: flex-start;
  padding: 1.5rem 1rem;
  overflow-x: hidden;
  -webkit-font-smoothing: antialiased;
}

/* ==========================================================================
   Piano App Container & Headers
   ========================================================================== */

.piano-app {
  width: 100%;
  max-width: 960px;
  display: flex;
  flex-direction: column;
  gap: 1.5rem;
  margin: 0 auto;
}

.header-section {
  text-align: center;
  padding: 0.5rem 0;
}

.app-title {
  font-size: 2rem;
  font-weight: 800;
  letter-spacing: -0.025em;
  background: linear-gradient(135deg, #ffffff 40%, var(--piano-trim-gold) 100%);
  -webkit-background-clip: text;
  -webkit-text-fill-color: transparent;
  margin-bottom: 0.35rem;
}

.app-subtitle {
  font-size: 0.95rem;
  color: var(--text-muted);
  font-weight: 400;
}

/* ==========================================================================
   Controls Panel & Sub-panels
   ========================================================================== */

.controls-panel {
  background: var(--panel-bg);
  backdrop-filter: blur(12px);
  border: 1px solid var(--panel-border);
  border-radius: 14px;
  padding: 1.25rem 1.5rem;
  display: flex;
  flex-direction: column;
  gap: 1.25rem;
  box-shadow: 0 16px 36px rgba(0, 0, 0, 0.35);
}

.controls-panel > .button-group:first-child,
.controls-top-bar {
  justify-content: space-between;
  width: 100%;
}

.control-group {
  display: flex;
  flex-direction: column;
  gap: 0.5rem;
  min-width: 140px;
}

.control-group-volume {
  flex-grow: 1;
  max-width: 240px;
}

.control-label {
  font-size: 0.8rem;
  font-weight: 600;
  color: var(--text-muted);
  text-transform: uppercase;
  letter-spacing: 0.05em;
}

.select-input {
  background: #262934;
  color: var(--text-main);
  border: 1px solid rgba(255, 255, 255, 0.12);
  border-radius: 8px;
  padding: 0.55rem 0.85rem;
  font-size: 0.9rem;
  font-family: inherit;
  outline: none;
  cursor: pointer;
  transition: border-color 0.15s ease, box-shadow 0.15s ease;
}

.select-input:focus {
  border-color: var(--accent-blue);
  box-shadow: 0 0 0 2px rgba(59, 130, 246, 0.25);
}

.select-input:focus-visible {
  outline: 2px solid var(--accent-blue);
  outline-offset: 2px;
}

.range-slider {
  appearance: none;
  -webkit-appearance: none;
  width: 100%;
  height: 6px;
  background: #2f3342;
  border-radius: 9999px;
  outline: none;
  cursor: pointer;
}

.range-slider:focus-visible {
  outline: 2px solid var(--accent-blue);
  outline-offset: 3px;
}

.range-slider::-webkit-slider-thumb {
  appearance: none;
  -webkit-appearance: none;
  width: 18px;
  height: 18px;
  border-radius: 50%;
  background: var(--accent-blue);
  cursor: pointer;
  box-shadow: 0 2px 6px rgba(0, 0, 0, 0.4);
  transition: transform 0.1s ease, background 0.15s ease;
}

.range-slider::-webkit-slider-thumb:hover {
  transform: scale(1.15);
  background: #60a5fa;
}

.range-slider::-moz-range-thumb {
  width: 18px;
  height: 18px;
  border: none;
  border-radius: 50%;
  background: var(--accent-blue);
  cursor: pointer;
  box-shadow: 0 2px 6px rgba(0, 0, 0, 0.4);
  transition: transform 0.1s ease, background 0.15s ease;
}

.range-slider::-moz-range-thumb:hover {
  transform: scale(1.15);
  background: #60a5fa;
}

.button-group {
  display: flex;
  flex-wrap: wrap;
  gap: 0.5rem;
  align-items: center;
}

.button-group-nowrap {
  flex-wrap: nowrap;
}

.action-btn {
  background: #2a2d3a;
  color: var(--text-main);
  border: 1px solid rgba(255, 255, 255, 0.1);
  border-radius: 8px;
  padding: 0.55rem 0.95rem;
  font-size: 0.85rem;
  font-weight: 500;
  cursor: pointer;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 0.4rem;
  transition: all 0.15s ease;
  user-select: none;
}

.action-btn:hover {
  background: #353949;
  border-color: rgba(255, 255, 255, 0.2);
}

.action-btn:active {
  transform: scale(0.97);
}

.action-btn:focus-visible {
  outline: 2px solid var(--accent-blue);
  outline-offset: 2px;
  box-shadow: 0 0 0 3px rgba(59, 130, 246, 0.35);
}

.action-btn.active {
  background: #3b4256;
  border-color: var(--accent-blue);
  color: #93c5fd;
}

.action-btn-primary {
  background: var(--accent-blue);
  border-color: var(--accent-blue);
  color: #ffffff;
}

.action-btn-primary:hover {
  background: var(--accent-blue-hover);
  border-color: var(--accent-blue-hover);
}

.action-btn-primary:focus-visible {
  outline: 2px solid #93c5fd;
  outline-offset: 2px;
}

.action-btn-danger {
  background: var(--accent-red);
  border-color: var(--accent-red);
  color: #ffffff;
}

.action-btn-danger:hover {
  background: var(--accent-red-hover);
  border-color: var(--accent-red-hover);
}

.action-btn-danger:focus-visible {
  outline: 2px solid #fca5a5;
  outline-offset: 2px;
}

.recorder-panel,
.demo-panel {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  justify-content: space-between;
  gap: 1rem;
  padding-top: 0.75rem;
  border-top: 1px solid rgba(255, 255, 255, 0.06);
}

/* ==========================================================================
   Status Bar & Indicators
   ========================================================================== */

.status-bar {
  display: flex;
  align-items: center;
  gap: 0.6rem;
  font-size: 0.85rem;
  color: var(--text-muted);
}

.indicator {
  width: 10px;
  height: 10px;
  border-radius: 50%;
  background: #4b5563;
  display: inline-block;
  transition: background-color 0.2s ease, box-shadow 0.2s ease;
}

.indicator.active {
  background: var(--accent-red);
  box-shadow: 0 0 10px var(--accent-red);
  animation: pulse 1.2s infinite;
}

@keyframes pulse {
  0% { transform: scale(0.95); opacity: 0.8; }
  50% { transform: scale(1.15); opacity: 1; }
  100% { transform: scale(0.95); opacity: 0.8; }
}

/* ==========================================================================
   Piano Keyboard Outer & Keybed
   ========================================================================== */

.keyboard-outer {
  background: var(--piano-body-color);
  padding: 1.25rem 1.25rem 1.5rem 1.25rem;
  border-radius: 16px;
  box-shadow: 0 24px 50px rgba(0, 0, 0, 0.6), inset 0 2px 4px rgba(255, 255, 255, 0.1);
  border: 2px solid #2d2e38;
  position: relative;
}

/* Top red felt lining typical of acoustic pianos */
.keyboard-outer::before {
  content: "";
  position: absolute;
  top: 1.25rem;
  left: 1.25rem;
  right: 1.25rem;
  height: 8px;
  background: var(--piano-felt-red);
  border-radius: 3px 3px 0 0;
  z-index: 10;
  box-shadow: inset 0 -2px 4px rgba(0, 0, 0, 0.4);
}

.keyboard-scroll {
  width: 100%;
  overflow-x: auto;
  overflow-y: hidden;
  padding-bottom: 0.25rem;
  -webkit-overflow-scrolling: touch;
}

.keyboard-scroll::-webkit-scrollbar {
  height: 6px;
}

.keyboard-scroll::-webkit-scrollbar-track {
  background: #14151a;
  border-radius: 4px;
}

.keyboard-scroll::-webkit-scrollbar-thumb {
  background: #2a2c38;
  border-radius: 4px;
}

.piano-keyboard {
  position: relative;
  min-width: 640px;
  height: 240px;
  margin: 0 auto;
  user-select: none;
  touch-action: none;
}

.white-keys-container {
  display: flex;
  width: 100%;
  height: 100%;
}

.black-keys-container {
  position: absolute;
  top: 0;
  left: 0;
  width: 100%;
  height: 60%;
  pointer-events: none;
}

/* ==========================================================================
   Key Common, White Key, Black Key Styles
   ========================================================================== */

.key {
  position: relative;
  cursor: pointer;
  user-select: none;
  -webkit-user-select: none;
  display: flex;
  align-items: flex-end;
  justify-content: center;
  transition: transform 0.05s ease, background 0.08s ease, box-shadow 0.05s ease;
}

.key:focus-visible {
  outline: 3px solid var(--accent-blue);
  outline-offset: -2px;
  z-index: 10;
}

.white-key {
  flex: 1 1 0%;
  height: 100%;
  background: linear-gradient(180deg, var(--white-key-base) 0%, var(--white-key-grad) 100%);
  border: 1px solid var(--white-key-border);
  border-top: none;
  border-radius: 0 0 6px 6px;
  box-shadow: inset 0 -4px 6px rgba(0, 0, 0, 0.15), 0 5px 8px rgba(0, 0, 0, 0.35);
  z-index: 1;
  padding-bottom: 0.85rem;
}

.white-key:hover {
  background: linear-gradient(180deg, #ffffff 0%, #ebebef 100%);
}

.white-key.key-active {
  background: linear-gradient(180deg, #e0ebff 0%, var(--white-key-active) 100%);
  transform: translateY(3px);
  box-shadow: inset 0 -2px 3px rgba(0, 0, 0, 0.2), 0 2px 4px rgba(0, 0, 0, 0.25);
}

.black-key {
  position: absolute;
  width: 7.2%;
  height: 100%;
  background: linear-gradient(180deg, var(--black-key-top) 0%, var(--black-key-base) 100%);
  border: 1px solid var(--black-key-border);
  border-top: none;
  border-radius: 0 0 4px 4px;
  box-shadow: -2px 3px 5px rgba(0, 0, 0, 0.6), inset 0 1px 1px rgba(255, 255, 255, 0.15);
  z-index: 2;
  pointer-events: auto;
  padding-bottom: 0.75rem;
}

.black-key:hover {
  background: linear-gradient(180deg, #1e2027 0%, #353843 100%);
}

.black-key.key-active {
  background: linear-gradient(180deg, #243352 0%, var(--black-key-active) 100%);
  transform: translateY(2px) scale(0.99);
  box-shadow: -1px 1px 3px rgba(0, 0, 0, 0.8);
}

/* ==========================================================================
   Key Labels (Note Name & Shortcut Key)
   ========================================================================== */

.key-label-wrapper {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 0.25rem;
  pointer-events: none;
}

.white-key .key-label-note {
  font-size: 0.95rem;
  font-weight: 700;
  color: #374151;
}

.white-key .key-label-key {
  font-size: 0.75rem;
  font-weight: 600;
  color: #6b7280;
  background: rgba(0, 0, 0, 0.05);
  padding: 0.1rem 0.35rem;
  border-radius: 4px;
}

.black-key .key-label-note {
  font-size: 0.75rem;
  font-weight: 600;
  color: #e5e7eb;
}

.black-key .key-label-key {
  font-size: 0.68rem;
  font-weight: 600;
  color: #9ca3af;
  background: rgba(255, 255, 255, 0.12);
  padding: 0.05rem 0.25rem;
  border-radius: 3px;
}

/* Active label highlights */
.white-key.key-active .key-label-note {
  color: var(--accent-blue);
}

.black-key.key-active .key-label-note {
  color: #93c5fd;
}

/* ==========================================================================
   Help & Instructions Box
   ========================================================================== */

.help-box {
  background: rgba(18, 20, 28, 0.6);
  border: 1px dashed rgba(255, 255, 255, 0.15);
  border-radius: 12px;
  padding: 1rem 1.25rem;
  font-size: 0.85rem;
  color: var(--text-muted);
  line-height: 1.6;
}

.help-box strong {
  color: var(--text-main);
}

.help-box kbd {
  background: #2a2d3b;
  color: #e2e8f0;
  border: 1px solid rgba(255, 255, 255, 0.2);
  border-bottom: 2px solid rgba(0, 0, 0, 0.5);
  border-radius: 4px;
  padding: 0.15rem 0.4rem;
  font-family: inherit;
  font-size: 0.8rem;
  font-weight: 600;
  display: inline-block;
  margin: 0 0.15rem;
}

/* ==========================================================================
   Responsive Adaptations
   ========================================================================== */

@media (max-width: 768px) {
  body {
    padding: 0.75rem 0.5rem;
  }

  .piano-app {
    gap: 1rem;
  }

  .app-title {
    font-size: 1.6rem;
  }

  .controls-panel {
    padding: 1rem;
    gap: 1rem;
  }

  .recorder-panel,
  .demo-panel {
    flex-direction: column;
    align-items: stretch;
    gap: 0.75rem;
  }

  .keyboard-outer {
    padding: 0.85rem 0.85rem 1rem 0.85rem;
  }

  .piano-keyboard {
    height: 200px;
  }
}

export interface PianoKeyItem {
  id: string;
  noteName: string;
  noteLabel: string;
  frequency: number;
  isBlack: boolean;
  keyboardKey: string;
  leftPercent?: number;
}

export type WaveformType = 'sine' | 'triangle' | 'sawtooth' | 'square';

export interface RecordedNote {
  noteId: string;
  timestamp: number;
  duration: number;
}

export interface DemoNoteItem {
  noteId: string;
  duration: number;
  delay: number;
}

export interface DemoSongItem {
  name: string;
  notes: DemoNoteItem[];
}

export type PlaybackStatus = 'idle' | 'recording' | 'playing';

import { WaveformType } from '../types';

interface ActiveVoice {
  oscillator: OscillatorNode;
  gainNode: GainNode;
  filterNode: BiquadFilterNode;
}

const MAX_POLYPHONY = 12;

class AudioEngine {
  private audioCtx: AudioContext | null = null;
  private masterGain: GainNode | null = null;
  private activeVoices: Map<string, ActiveVoice> = new Map();
  private currentWaveform: WaveformType = 'triangle';
  private currentVolume: number = 0.5;

  private initContextIfNeeded(): AudioContext {
    if (!this.audioCtx) {
      const AudioCtxClass = window.AudioContext || (window as unknown as { webkitAudioContext: typeof AudioContext }).webkitAudioContext;
      this.audioCtx = new AudioCtxClass();

      this.masterGain = this.audioCtx.createGain();
      this.masterGain.gain.setValueAtTime(this.currentVolume, this.audioCtx.currentTime);
      this.masterGain.connect(this.audioCtx.destination);
    }

    if (this.audioCtx.state === 'suspended') {
      this.audioCtx.resume().catch((err) => {
        console.warn('AudioContext resume was prevented or failed:', err);
      });
    }

    return this.audioCtx;
  }

  public setWaveform(type: WaveformType): void {
    this.currentWaveform = type;
  }

  public getWaveform(): WaveformType {
    return this.currentWaveform;
  }

  public setVolume(volume: number): void {
    this.currentVolume = Math.max(0, Math.min(1, volume));
    if (this.masterGain && this.audioCtx) {
      const now = this.audioCtx.currentTime;
      this.masterGain.gain.cancelScheduledValues(now);
      this.masterGain.gain.setTargetAtTime(this.currentVolume, now, 0.02);
    }
  }

  public getVolume(): number {
    return this.currentVolume;
  }

  public startNote(noteId: string, frequency: number): void {
    const ctx = this.initContextIfNeeded();
    if (!this.masterGain) return;

    if (this.activeVoices.has(noteId)) {
      this.stopNote(noteId);
    }

    // ボイススティーリング (最大同時発音数の制限超過時に最古のボイスを解放)
    if (this.activeVoices.size >= MAX_POLYPHONY) {
      const oldestNoteId = this.activeVoices.keys().next().value;
      if (oldestNoteId) {
        this.stopNote(oldestNoteId);
      }
    }

    const now = ctx.currentTime;
    const osc = ctx.createOscillator();
    const voiceGain = ctx.createGain();
    const filter = ctx.createBiquadFilter();

    osc.type = this.currentWaveform;
    osc.frequency.setValueAtTime(frequency, now);

    filter.type = 'lowpass';
    filter.frequency.setValueAtTime(Math.min(frequency * 5, 12000), now);
    filter.Q.setValueAtTime(1, now);

    // ADSR Envelope
    const attackTime = 0.015;
    const decayTime = 0.12;
    const sustainLevel = 0.65;

    voiceGain.gain.setValueAtTime(0.0001, now);
    voiceGain.gain.exponentialRampToValueAtTime(1.0, now + attackTime);
    voiceGain.gain.exponentialRampToValueAtTime(sustainLevel, now + attackTime + decayTime);

    osc.connect(filter);
    filter.connect(voiceGain);
    voiceGain.connect(this.masterGain);

    // 再生完了時にノードの切断を安全に実施 (タイマー遅延・リーク防止)
    osc.onended = () => {
      osc.disconnect();
      filter.disconnect();
      voiceGain.disconnect();
    };

    osc.start(now);

    this.activeVoices.set(noteId, {
      oscillator: osc,
      gainNode: voiceGain,
      filterNode: filter
    });
  }

  public stopNote(noteId: string): void {
    const voice = this.activeVoices.get(noteId);
    if (!voice || !this.audioCtx) return;

    const ctx = this.audioCtx;
    const now = ctx.currentTime;
    const releaseTime = 0.18;

    voice.gainNode.gain.cancelScheduledValues(now);
    const currentGain = Math.max(voice.gainNode.gain.value, 0.0001);
    voice.gainNode.gain.setValueAtTime(currentGain, now);
    voice.gainNode.gain.exponentialRampToValueAtTime(0.0001, now + releaseTime);

    // stop() 呼び出し後に onended コールバックで disconnect() が実行される
    voice.oscillator.stop(now + releaseTime + 0.02);

    this.activeVoices.delete(noteId);
  }

  public stopAllNotes(): void {
    const noteIds = Array.from(this.activeVoices.keys());
    for (const noteId of noteIds) {
      this.stopNote(noteId);
    }
  }
}

export const audioEngine = new AudioEngine();

import React from 'react';
import { PianoKeyItem } from '../types';

interface PianoKeyboardProps {
  keys?: PianoKeyItem[];
  activeNotes?: Set<string>;
  showNoteNames?: boolean;
  showKeyLabels?: boolean;
  onNoteStart?: (noteId: string) => void;
  onNoteStop?: (noteId: string) => void;
}

const PianoKeyboard = ({
  keys = [],
  activeNotes = new Set<string>(),
  showNoteNames = true,
  showKeyLabels = true,
  onNoteStart,
  onNoteStop
}: PianoKeyboardProps) => {
  const whiteKeys = keys.filter((k) => !k.isBlack);
  const blackKeys = keys.filter((k) => k.isBlack);

  const handlePointerDown = (noteId: string, e: React.PointerEvent) => {
    e.preventDefault();
    onNoteStart?.(noteId);
  };

  const handlePointerUp = (noteId: string, e: React.PointerEvent) => {
    e.preventDefault();
    onNoteStop?.(noteId);
  };

  const handlePointerEnter = (noteId: string, e: React.PointerEvent) => {
    if (e.buttons === 1) {
      onNoteStart?.(noteId);
    }
  };

  const handlePointerLeave = (noteId: string, e: React.PointerEvent) => {
    if (e.buttons === 1) {
      onNoteStop?.(noteId);
    }
  };

  const handleKeyDown = (noteId: string, e: React.KeyboardEvent) => {
    if (e.key === 'Enter' || e.key === ' ') {
      e.preventDefault();
      if (!activeNotes.has(noteId)) {
        onNoteStart?.(noteId);
      }
    }
  };

  const handleKeyUp = (noteId: string, e: React.KeyboardEvent) => {
    if (e.key === 'Enter' || e.key === ' ') {
      e.preventDefault();
      onNoteStop?.(noteId);
    }
  };

  return (
    <div className="keyboard-outer">
      <div className="keyboard-scroll">
        <div className="piano-keyboard">
          <div className="white-keys-container">
            {whiteKeys.map((keyItem) => {
              const isActive = activeNotes.has(keyItem.id);
              const keyClassName = isActive ? 'key white-key key-active' : 'key white-key';

              return (
                <div
                  key={keyItem.id}
                  className={keyClassName}
                  role="button"
                  tabIndex={0}
                  aria-label={`鍵盤 ${keyItem.noteLabel}`}
                  onPointerDown={(e) => handlePointerDown(keyItem.id, e)}
                  onPointerUp={(e) => handlePointerUp(keyItem.id, e)}
                  onPointerEnter={(e) => handlePointerEnter(keyItem.id, e)}
                  onPointerLeave={(e) => handlePointerLeave(keyItem.id, e)}
                  onPointerCancel={(e) => handlePointerUp(keyItem.id, e)}
                  onKeyDown={(e) => handleKeyDown(keyItem.id, e)}
                  onKeyUp={(e) => handleKeyUp(keyItem.id, e)}
                >
                  <div className="key-label-wrapper">
                    {showNoteNames && (
                      <span className="key-label-note">{keyItem.noteLabel}</span>
                    )}
                    {showKeyLabels && (
                      <span className="key-label-key">{keyItem.keyboardKey.toUpperCase()}</span>
                    )}
                  </div>
                </div>
              );
            })}
          </div>

          <div className="black-keys-container">
            {blackKeys.map((keyItem) => {
              const isActive = activeNotes.has(keyItem.id);
              const keyClassName = isActive ? 'key black-key key-active' : 'key black-key';
              const leftPos = keyItem.leftPercent !== undefined ? `${keyItem.leftPercent}%` : '0%';

              return (
                <div
                  key={keyItem.id}
                  className={keyClassName}
                  style={{ left: leftPos }}
                  role="button"
                  tabIndex={0}
                  aria-label={`鍵盤 ${keyItem.noteLabel}`}
                  onPointerDown={(e) => handlePointerDown(keyItem.id, e)}
                  onPointerUp={(e) => handlePointerUp(keyItem.id, e)}
                  onPointerEnter={(e) => handlePointerEnter(keyItem.id, e)}
                  onPointerLeave={(e) => handlePointerLeave(keyItem.id, e)}
                  onPointerCancel={(e) => handlePointerUp(keyItem.id, e)}
                  onKeyDown={(e) => handleKeyDown(keyItem.id, e)}
                  onKeyUp={(e) => handleKeyUp(keyItem.id, e)}
                >
                  <div className="key-label-wrapper">
                    {showNoteNames && (
                      <span className="key-label-note">{keyItem.noteLabel}</span>
                    )}
                    {showKeyLabels && (
                      <span className="key-label-key">{keyItem.keyboardKey.toUpperCase()}</span>
                    )}
                  </div>
                </div>
              );
            })}
          </div>
        </div>
      </div>
    </div>
  );
};

