interface PlaybackEvent {
  time: number;
  type: 'start' | 'stop';
  noteId: string;
}

const keyToNoteMap: Record<string, PianoKeyItem> = {};
const idToNoteMap: Record<string, PianoKeyItem> = {};

for (const key of PIANO_KEYS) {
  keyToNoteMap[key.keyboardKey.toLowerCase()] = key;
  idToNoteMap[key.id] = key;
}

const App = () => {
  const [activeNotes, setActiveNotes] = useState<Set<string>>(new Set());
  const [waveform, setWaveform] = useState<WaveformType>('triangle');
  const [volume, setVolume] = useState<number>(0.5);
  const [showNoteNames, setShowNoteNames] = useState<boolean>(true);
  const [showKeyLabels, setShowKeyLabels] = useState<boolean>(true);

  const [isRecording, setIsRecording] = useState<boolean>(false);
  const [recordedNotes, setRecordedNotes] = useState<RecordedNote[]>([]);
  const [isPlayingRecorded, setIsPlayingRecorded] = useState<boolean>(false);

  const [selectedDemoIndex, setSelectedDemoIndex] = useState<number>(0);
  const [isPlayingDemo, setIsPlayingDemo] = useState<boolean>(false);

  const recordStartTimeRef = useRef<number>(0);
  const notePressStartTimesRef = useRef<Map<string, number>>(new Map());
  const isRecordingRef = useRef<boolean>(false);

  // Web Workerベースの高精度タイマーによるシーケンサー制御
  const workerRef = useRef<Worker | null>(null);
  const sequenceEventsRef = useRef<PlaybackEvent[]>([]);
  const sequenceEventIndexRef = useRef<number>(0);
  const sequenceStartTimeRef = useRef<number>(0);
  const sequenceTotalDurationRef = useRef<number>(0);
  const sequenceTypeRef = useRef<'recorded' | 'demo' | null>(null);

  isRecordingRef.current = isRecording;

  const playNote = useCallback((noteId: string) => {
    const keyItem = idToNoteMap[noteId];
    if (!keyItem) return;

    audioEngine.startNote(noteId, keyItem.frequency);
    setActiveNotes((prev) => {
      const updated = new Set(prev);
      updated.add(noteId);
      return updated;
    });

    if (isRecordingRef.current) {
      notePressStartTimesRef.current.set(noteId, Date.now());
    }
  }, []);

  const stopNote = useCallback((noteId: string) => {
    audioEngine.stopNote(noteId);
    setActiveNotes((prev) => {
      const updated = new Set(prev);
      updated.delete(noteId);
      return updated;
    });

    if (isRecordingRef.current && notePressStartTimesRef.current.has(noteId)) {
      const startTime = notePressStartTimesRef.current.get(noteId) || Date.now();
      const duration = Math.max(Date.now() - startTime, 100);
      const timestamp = startTime - recordStartTimeRef.current;

      setRecordedNotes((prev) => [...prev, { noteId, timestamp, duration }]);
      notePressStartTimesRef.current.delete(noteId);
    }
  }, []);

  const stopSequencer = useCallback(() => {
    if (workerRef.current) {
      workerRef.current.postMessage('stop');
    }
    sequenceEventsRef.current = [];
    sequenceEventIndexRef.current = 0;
    sequenceTypeRef.current = null;
    audioEngine.stopAllNotes();
    setActiveNotes(new Set());
  }, []);

  const clearAllScheduledAudio = useCallback(() => {
    stopSequencer();
    setIsPlayingRecorded(false);
    setIsPlayingDemo(false);
  }, [stopSequencer]);

  // Web Worker の初期化（タイマースロットリング防止）
  useEffect(() => {
    const workerBlob = new Blob(
      [
        `
        let intervalId = null;
        self.onmessage = function(e) {
          if (e.data === 'start') {
            if (intervalId) clearInterval(intervalId);
            intervalId = setInterval(function() {
              self.postMessage('tick');
            }, 15);
          } else if (e.data === 'stop') {
            if (intervalId) {
              clearInterval(intervalId);
              intervalId = null;
            }
          }
        };
      `
      ],
      { type: 'application/javascript' }
    );

    const workerUrl = URL.createObjectURL(workerBlob);
    const worker = new Worker(workerUrl);

    worker.onmessage = () => {
      if (!sequenceTypeRef.current) return;

      const elapsed = performance.now() - sequenceStartTimeRef.current;
      const events = sequenceEventsRef.current;

      while (
        sequenceEventIndexRef.current < events.length &&
        events[sequenceEventIndexRef.current].time <= elapsed
      ) {
        const ev = events[sequenceEventIndexRef.current];
        if (ev.type === 'start') {
          playNote(ev.noteId);
        } else {
          stopNote(ev.noteId);
        }
        sequenceEventIndexRef.current += 1;
      }

      if (
        sequenceEventIndexRef.current >= events.length &&
        elapsed >= sequenceTotalDurationRef.current
      ) {
        const type = sequenceTypeRef.current;
        stopSequencer();
        if (type === 'recorded') {
          setIsPlayingRecorded(false);
        } else if (type === 'demo') {
          setIsPlayingDemo(false);
        }
      }
    };

    workerRef.current = worker;

    return () => {
      worker.postMessage('stop');
      worker.terminate();
      URL.revokeObjectURL(workerUrl);
    };
  }, [playNote, stopNote, stopSequencer]);

  const handleWaveformChange = (newWaveform: WaveformType) => {
    setWaveform(newWaveform);
    audioEngine.setWaveform(newWaveform);
  };

  const handleVolumeChange = (newVolume: number) => {
    setVolume(newVolume);
    audioEngine.setVolume(newVolume);
  };

  const handleToggleNoteNames = () => {
    setShowNoteNames((prev) => !prev);
  };

  const handleToggleKeyLabels = () => {
    setShowKeyLabels((prev) => !prev);
  };

  const handleToggleRecording = () => {
    if (isRecording) {
      // 押下中のまま録音停止されたノートを確定してコミット
      const now = Date.now();
      const danglingNotes: RecordedNote[] = [];

      notePressStartTimesRef.current.forEach((startTime, noteId) => {
        const duration = Math.max(now - startTime, 100);
        const timestamp = startTime - recordStartTimeRef.current;
        danglingNotes.push({ noteId, timestamp, duration });
      });

      notePressStartTimesRef.current.clear();

      if (danglingNotes.length > 0) {
        setRecordedNotes((prev) => [...prev, ...danglingNotes]);
      }

      setIsRecording(false);
    } else {
      clearAllScheduledAudio();
      setRecordedNotes([]);
      notePressStartTimesRef.current.clear();
      recordStartTimeRef.current = Date.now();
      setIsRecording(true);
    }
  };

  const handlePlayRecording = () => {
    if (isPlayingRecorded) {
      clearAllScheduledAudio();
      return;
    }

    if (recordedNotes.length === 0) return;

    clearAllScheduledAudio();
    setIsPlayingRecorded(true);

    const events: PlaybackEvent[] = [];
    let maxTime = 0;

    for (const item of recordedNotes) {
      events.push({
        time: item.timestamp,
        type: 'start',
        noteId: item.noteId
      });
      events.push({
        time: item.timestamp + item.duration,
        type: 'stop',
        noteId: item.noteId
      });
      if (item.timestamp + item.duration > maxTime) {
        maxTime = item.timestamp + item.duration;
      }
    }

    events.sort((a, b) => a.time - b.time);

    sequenceEventsRef.current = events;
    sequenceEventIndexRef.current = 0;
    sequenceStartTimeRef.current = performance.now();
    sequenceTotalDurationRef.current = maxTime + 300;
    sequenceTypeRef.current = 'recorded';

    if (workerRef.current) {
      workerRef.current.postMessage('start');
    }
  };

  const handleSelectDemoSong = (index: number) => {
    setSelectedDemoIndex(index);
    if (isPlayingDemo) {
      clearAllScheduledAudio();
    }
  };

  const handlePlayDemoSong = () => {
    clearAllScheduledAudio();
    if (isRecording) {
      setIsRecording(false);
    }

    const demo = DEMO_SONGS[selectedDemoIndex];
    if (!demo || demo.notes.length === 0) return;

    setIsPlayingDemo(true);

    const events: PlaybackEvent[] = [];
    let maxTime = 0;

    for (const item of demo.notes) {
      events.push({
        time: item.delay,
        type: 'start',
        noteId: item.noteId
      });
      events.push({
        time: item.delay + item.duration,
        type: 'stop',
        noteId: item.noteId
      });
      if (item.delay + item.duration > maxTime) {
        maxTime = item.delay + item.duration;
      }
    }

    events.sort((a, b) => a.time - b.time);

    sequenceEventsRef.current = events;
    sequenceEventIndexRef.current = 0;
    sequenceStartTimeRef.current = performance.now();
    sequenceTotalDurationRef.current = maxTime + 400;
    sequenceTypeRef.current = 'demo';

    if (workerRef.current) {
      workerRef.current.postMessage('start');
    }
  };

  const handleStopDemoSong = () => {
    clearAllScheduledAudio();
  };

  useEffect(() => {
    const handleKeyDown = (e: KeyboardEvent) => {
      if (e.isComposing) return;
      if (e.repeat || e.target instanceof HTMLInputElement || e.target instanceof HTMLSelectElement) {
        return;
      }
      const key = e.key.toLowerCase();
      const matchedKeyItem = keyToNoteMap[key];
      if (matchedKeyItem) {
        e.preventDefault();
        playNote(matchedKeyItem.id);
      }
    };

    const handleKeyUp = (e: KeyboardEvent) => {
      if (e.isComposing) return;
      const key = e.key.toLowerCase();
      const matchedKeyItem = keyToNoteMap[key];
      if (matchedKeyItem) {
        e.preventDefault();
        stopNote(matchedKeyItem.id);
      }
    };

    window.addEventListener('keydown', handleKeyDown);
    window.addEventListener('keyup', handleKeyUp);

    return () => {
      window.removeEventListener('keydown', handleKeyDown);
      window.removeEventListener('keyup', handleKeyUp);
      clearAllScheduledAudio();
    };
  }, [playNote, stopNote, clearAllScheduledAudio]);

  return (
    <div className="piano-app">
      <header className="header-section">
        <h1 className="app-title">Web ピアノスタジオ</h1>
        <p className="app-subtitle">
          Web Audio API による本格サウンド・マウス / タッチ / PCキーボード演奏対応
        </p>
      </header>

      <Controls
        waveform={waveform}
        volume={volume}
        showNoteNames={showNoteNames}
        showKeyLabels={showKeyLabels}
        isRecording={isRecording}
        isPlayingRecorded={isPlayingRecorded}
        hasRecordedNotes={recordedNotes.length > 0}
        recordedCount={recordedNotes.length}
        demoSongs={DEMO_SONGS}
        selectedDemoIndex={selectedDemoIndex}
        isPlayingDemo={isPlayingDemo}
        onWaveformChange={handleWaveformChange}
        onVolumeChange={handleVolumeChange}
        onToggleNoteNames={handleToggleNoteNames}
        onToggleKeyLabels={handleToggleKeyLabels}
        onToggleRecording={handleToggleRecording}
        onPlayRecording={handlePlayRecording}
        onSelectDemoSong={handleSelectDemoSong}
        onPlayDemoSong={handlePlayDemoSong}
        onStopDemoSong={handleStopDemoSong}
      />

      <PianoKeyboard
        keys={PIANO_KEYS}
        activeNotes={activeNotes}
        showNoteNames={showNoteNames}
        showKeyLabels={showKeyLabels}
        onNoteStart={playNote}
        onNoteStop={stopNote}
      />

      <div className="help-box">
        <strong>PCキーボード演奏方法:</strong>
        <br />
        白鍵: <kbd>A</kbd> (ド), <kbd>S</kbd> (レ), <kbd>D</kbd> (ミ), <kbd>F</kbd> (ファ), <kbd>G</kbd> (ソ), <kbd>H</kbd> (ラ), <kbd>J</kbd> (シ), <kbd>K</kbd> (高ド)
        <br />
        黒鍵: <kbd>W</kbd> (ド#), <kbd>E</kbd> (レ#), <kbd>T</kbd> (ファ#), <kbd>Y</kbd> (ソ#), <kbd>U</kbd> (ラ#)
        <br />
        ※ スマートフォンやタブレットでは鍵盤を直接タッチ、またはなぞってスライド演奏ができます。
      </div>
    </div>
  );
};

